"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";

const glossButtonVariants = cva(
  [
    /* Base. */
    "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full bg-linear-to-b from-[color-mix(in_oklch,var(--primary),white_14%)] to-primary bg-clip-padding text-sm font-medium whitespace-nowrap text-primary-foreground ring-offset-background outline-none select-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-1 aria-invalid:focus-visible:ring-destructive",
    /* States. */
    "shadow-[inset_0_1px_0_rgb(255_255_255_/_0.4),inset_0_-2px_4px_rgb(0_0_0_/_0.12),0_2px_4px_rgb(0_0_0_/_0.08)] transition-[filter,opacity,transform] duration-200 hover:brightness-105 active:scale-[0.985] disabled:pointer-events-none disabled:bg-muted disabled:bg-none disabled:text-muted-foreground disabled:opacity-50 disabled:shadow-none aria-invalid:from-[color-mix(in_oklch,var(--destructive),white_12%)] aria-invalid:to-destructive aria-invalid:text-white",
    /* Icons. */
    "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  ],
  {
    variants: {
      size: {
        default:
          "h-8 gap-1.5 px-3 has-data-[icon=inline-end]:pe-2.5 has-data-[icon=inline-start]:ps-2.5",
        xs: "h-6 gap-1 px-2.5 text-xs has-data-[icon=inline-end]:pe-2 has-data-[icon=inline-start]:ps-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 px-3 text-[0.8rem] has-data-[icon=inline-end]:pe-2.5 has-data-[icon=inline-start]:ps-2.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-3.5 has-data-[icon=inline-end]:pe-3 has-data-[icon=inline-start]:ps-3",
        icon: "size-8",
        "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-7 [&_svg:not([class*='size-'])]:size-3.5",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      size: "default",
    },
  },
);

function GlossButton({
  className,
  size = "default",
  render,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof glossButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="gloss-button"
      data-size={size}
      className={cn(glossButtonVariants({ size, className }))}
      nativeButton={render ? false : nativeButton}
      render={render}
      {...props}
    />
  );
}

export { GlossButton, glossButtonVariants };
export default GlossButton;

